import React, { useState, useEffect, useRef } from 'react';
import { Card, Input, Button, List, Typography, Spin, Space, Divider } from 'antd';
import { SendOutlined, DownloadOutlined, BarChartOutlined, FileTextOutlined } from '@ant-design/icons';
import axios from 'axios';
import TypewriterText from './TypewriterText';

const { Text } = Typography;

const Chat = ({ onShowDashboard }) => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState([
    { 
      type: 'bot', 
      text: 'Olá! Sou o Cortex AI, seu assistente para monitoramento de comunicação e reputação. Posso ajudá-lo a encontrar notícias sobre qualquer tema, empresa ou assunto que você queira analisar. O que gostaria de monitorar hoje?',
      isTyping: false
    }
  ]);
  const [loading, setLoading] = useState(false);
  const [noticias, setNoticias] = useState([]);
  const [temaAtual, setTemaAtual] = useState('');
  const [aguardandoPeriodo, setAguardandoPeriodo] = useState(false);
  const [aguardandoAcao, setAguardandoAcao] = useState(false);
  const [currentTypingIndex, setCurrentTypingIndex] = useState(0);
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Detectar saudações e perguntas sobre funcionalidades
  const detectarTipoMensagem = (texto) => {
    const lower = texto.toLowerCase();

    // Saudações
    if (lower.includes('oi') || lower.includes('olá') || lower.includes('ola') || lower.includes('hello') || lower.includes('hi')) {
      return 'saudacao';
    }

    // Perguntas sobre funcionalidades
    if (lower.includes('o que você faz') || lower.includes('o que voce faz') || lower.includes('como funciona') || lower.includes('ajuda') || lower.includes('help')) {
      return 'funcionalidade';
    }

    return 'busca';
  };

  // Gerar resposta baseada no tipo de mensagem
  const gerarRespostaAutomatica = (tipo) => {
    switch (tipo) {
      case 'saudacao':
        return 'Olá! Que bom ver você por aqui! 😊 Sou o Cortex AI e estou aqui para ajudá-lo a monitorar temas, empresas ou assuntos na mídia. Posso buscar notícias reais e gerar relatórios e dashboards para você. O que gostaria de analisar hoje?';
      case 'funcionalidade':
        return 'Sou o Cortex AI, seu assistente especializado em monitoramento de comunicação e reputação! 🎯\n\nPosso ajudá-lo com:\n• Buscar notícias sobre qualquer tema ou empresa\n• Gerar resumos automáticos do conteúdo\n• Preparar planilhas para exportação\n• Criar dashboards interativos com indicadores\n• Analisar sentimentos e tendências\n\nBasta me dizer o que você quer monitorar!';
      default:
        return null;
    }
  };

  // Adicionar mensagem com animação de digitação
  const adicionarMensagemBot = (texto, callback = null) => {
    const novaMensagem = {
      type: 'bot',
      text: texto,
      isTyping: true
    };

    setMessages(prev => [...prev, novaMensagem]);

    // Simular tempo de "digitação" baseado no tamanho do texto
    const tempoDigitacao = Math.min(texto.length * 30, 3000);

    setTimeout(() => {
      setMessages(prev => 
        prev.map((msg, index) => 
          index === prev.length - 1 
            ? { ...msg, isTyping: false }
            : msg
        )
      );
      if (callback) callback();
    }, tempoDigitacao);
  };

  // Perguntar se pode ajudar em algo mais
  const perguntarSePodeAjudar = () => {
    setTimeout(() => {
      adicionarMensagemBot('Posso ajudá-lo com mais alguma coisa? 🤔');
    }, 1000);
  };

  const handleSend = async (customInput) => {
    const userInput = typeof customInput === 'string' ? customInput : input;
    if (!userInput.trim()) return;

    // Adicionar mensagem do usuário
    setMessages(prev => [...prev, { type: 'user', text: userInput }]);
    setLoading(true);
    setAguardandoPeriodo(false);
    setAguardandoAcao(false);

    try {
      // Detectar tipo de mensagem
      const tipoMensagem = detectarTipoMensagem(userInput);

      if (tipoMensagem !== 'busca') {
        // Resposta automática para saudações e perguntas
        const respostaAutomatica = gerarRespostaAutomatica(tipoMensagem);
        adicionarMensagemBot(respostaAutomatica, () => {
          setLoading(false);
          perguntarSePodeAjudar();
        });
        setInput('');
        return;
      }

      // Buscar notícias
      const res = await axios.post('http://localhost:4000/api/noticias', { termo: userInput });
      const noticiasResp = res.data;
      setNoticias(noticiasResp);
      setTemaAtual(userInput);

      if (noticiasResp.length === 0) {
        adicionarMensagemBot(
          'Não encontrei notícias recentes sobre esse tema. 😕\n\nQue tal tentar outro assunto ou perguntar de outra forma? Posso ajudar com temas como:\n• Dia dos Namorados\n• Energia Nuclear\n• Papa Leão XIV\n• The Town\n• Maternidade\n\nOu qualquer outro tema que você queira monitorar!',
          () => {
            setLoading(false);
            perguntarSePodeAjudar();
          }
        );
      } else {
        let resposta = `Encontrei ${noticiasResp.length} notícias sobre "${userInput}"! 📰\n\n`;

        if (noticiasResp.length > 3) {
          resposta += `Com essa quantidade de notícias, posso oferecer algumas opções:\n\n`;
          resposta += `A) 📝 Gerar um resumo do conteúdo dessas notícias\n`;
          resposta += `B) 📊 Preparar uma planilha para você exportar\n`;
          resposta += `C) 📈 Criar um dashboard com indicadores e gráficos\n\n`;
          resposta += `Primeiro, gostaria de filtrar por algum período específico? (ex: últimos 7 dias, mês passado, etc)`;
        } else {
          resposta += `Gostaria de ver notícias de algum período específico? (ex: últimos 7 dias, mês passado, etc)`;
        }

        adicionarMensagemBot(resposta, () => {
          setAguardandoPeriodo(true);
          setLoading(false);
        });
      }
    } catch (e) {
      adicionarMensagemBot(
        'Ops! Tive um probleminha ao buscar as notícias agora. 😅\n\nQue tal tentar novamente em alguns instantes ou perguntar sobre outro tema?',
        () => {
          setLoading(false);
          perguntarSePodeAjudar();
        }
      );
    }
    setInput('');
  };

  const handlePeriodo = (periodo) => {
    setMessages(prev => [...prev, { type: 'user', text: periodo }]);

    let resposta = `Perfeito! Aqui estão as notícias do período: ${periodo}. 📅\n\n`;

    // Mostrar algumas notícias como exemplo
    const noticiasExemplo = noticias.slice(0, 3);
    noticiasExemplo.forEach((n, index) => {
      resposta += `${index + 1}. **${n.titulo}**\n`;
      resposta += `   📰 ${n.fonte} - ${new Date(n.data).toLocaleDateString('pt-BR')}\n`;
      resposta += `   ${n.descricao.substring(0, 100)}...\n\n`;
    });

    if (noticias.length > 3) {
      resposta += `E mais ${noticias.length - 3} notícias...\n\n`;
    }

    if (noticias.length > 3) {
      resposta += `Agora, o que você gostaria que eu fizesse?\n\n`;
      resposta += `A) 📝 Gerar um resumo do conteúdo dessas notícias\n`;
      resposta += `B) 📊 Preparar uma planilha para você exportar\n`;
      resposta += `C) 📈 Criar um dashboard com indicadores e gráficos`;
    } else {
      resposta += `Deseja baixar essas notícias em uma planilha ou gerar um dashboard com dados sobre elas?`;
    }

    adicionarMensagemBot(resposta, () => {
      setAguardandoAcao(true);
    });
    setAguardandoPeriodo(false);
  };

  const handleAcao = async (acao) => {
    setMessages(prev => [...prev, { type: 'user', text: acao }]);

    let resposta = '';
    if (acao === 'resumo') {
      resposta = '📝 Gerando um resumo inteligente do conteúdo das notícias...\n\n';
      // Aqui você pode implementar a lógica de resumo
      resposta += '**Resumo das principais notícias:**\n\n';
      noticias.slice(0, 5).forEach((n, index) => {
        resposta += `• ${n.titulo}\n`;
        resposta += `  Sentimento: ${n.sentimento === 'positivo' ? '😊' : n.sentimento === 'negativo' ? '😞' : '😐'} ${n.sentimento}\n`;
        resposta += `  Fonte: ${n.fonte}\n\n`;
      });
    } else if (acao === 'planilha') {
      resposta = '📊 Preparando planilha para download...\n\n';
      resposta += 'Sua planilha está sendo gerada com todos os dados das notícias encontradas. Em breve estará disponível para download!';
    } else if (acao === 'dashboard') {
      resposta = '📈 Gerando dashboard com indicadores das notícias...\n\n';
      resposta += 'Criando visualizações interativas com gráficos, tabelas e métricas importantes...';
    }

    adicionarMensagemBot(resposta, () => {
      setAguardandoAcao(false);

      if (acao === 'dashboard' && onShowDashboard) {
        setLoading(true);
        axios.post('http://localhost:4000/api/dashboard', { termo: temaAtual })
          .then(res => {
            onShowDashboard(res.data);
            adicionarMensagemBot('✅ Dashboard criado com sucesso! Você pode visualizá-lo na tela ao lado.', () => {
              setLoading(false);
              perguntarSePodeAjudar();
            });
          })
          .catch(e => {
            adicionarMensagemBot('❌ Erro ao gerar o dashboard. Tente novamente em alguns instantes.', () => {
              setLoading(false);
              perguntarSePodeAjudar();
            });
          });
      } else {
        setTimeout(() => {
          perguntarSePodeAjudar();
        }, 2000);
      }
    });
  };

  return (
    <div style={{ width: '100%', maxWidth: 420, margin: '0 auto', height: '100%', display: 'flex', flexDirection: 'column' }}>
      <div style={{ background: '#fff', borderRadius: 12, boxShadow: '0 2px 12px #e6e6e6', flex: 1, minHeight: 400, display: 'flex', flexDirection: 'column', position: 'relative', height: '100%' }}>
        <div style={{ flex: 1, overflowY: 'auto', padding: 24 }}>
          <List
            dataSource={messages}
            renderItem={(msg, index) => (
              <List.Item style={{ 
                justifyContent: msg.type === 'user' ? 'flex-end' : 'flex-start', 
                background: msg.type === 'user' ? '#e6f7ff' : 'transparent', 
                borderRadius: 8, 
                margin: '8px 0', 
                border: msg.type === 'user' ? '1px solid #bae7ff' : 'none',
                padding: '12px 16px'
              }}>
                <div style={{ maxWidth: '85%' }}>
                  {msg.isTyping ? (
                    <TypewriterText 
                      text={msg.text} 
                      speed={20}
                      style={{ fontSize: '14px', lineHeight: '1.5' }}
                    />
                  ) : (
                    <Text style={{ fontSize: '14px', lineHeight: '1.5', whiteSpace: 'pre-wrap' }}>
                      {msg.text}
                    </Text>
                  )}
                </div>
              </List.Item>
            )}
          />
          {loading && (
            <div style={{ textAlign: 'center', margin: '10px 0' }}>
              <Spin size="small" />
              <Text type="secondary" style={{ marginLeft: 8 }}>Processando...</Text>
            </div>
          )}
          {aguardandoPeriodo && (
            <div style={{ margin: '16px 0' }}>
              <Text strong style={{ display: 'block', marginBottom: 8 }}>Escolha um período:</Text>
              <Space wrap>
                <Button size="small" onClick={() => handlePeriodo('últimos 7 dias')}>Últimos 7 dias</Button>
                <Button size="small" onClick={() => handlePeriodo('mês passado')}>Mês passado</Button>
                <Button size="small" onClick={() => handlePeriodo('todo o período')}>Todo o período</Button>
              </Space>
            </div>
          )}
          {aguardandoAcao && noticias.length > 3 && (
            <div style={{ margin: '16px 0' }}>
              <Text strong style={{ display: 'block', marginBottom: 8 }}>O que você gostaria?</Text>
              <Space direction="vertical" style={{ width: '100%' }}>
                <Button 
                  icon={<FileTextOutlined />} 
                  onClick={() => handleAcao('resumo')}
                  style={{ width: '100%', textAlign: 'left', justifyContent: 'flex-start' }}
                >
                  A) Gerar resumo do conteúdo
                </Button>
                <Button 
                  icon={<DownloadOutlined />} 
                  onClick={() => handleAcao('planilha')}
                  style={{ width: '100%', textAlign: 'left', justifyContent: 'flex-start' }}
                >
                  B) Preparar planilha para exportar
                </Button>
                <Button 
                  icon={<BarChartOutlined />} 
                  onClick={() => handleAcao('dashboard')}
                  style={{ width: '100%', textAlign: 'left', justifyContent: 'flex-start' }}
                >
                  C) Criar dashboard com indicadores
                </Button>
              </Space>
            </div>
          )}
          {aguardandoAcao && noticias.length <= 3 && (
            <div style={{ margin: '16px 0' }}>
              <Text strong style={{ display: 'block', marginBottom: 8 }}>O que você gostaria?</Text>
              <Space>
                <Button icon={<DownloadOutlined />} onClick={() => handleAcao('planilha')}>
                  Baixar planilha
                </Button>
                <Button icon={<BarChartOutlined />} onClick={() => handleAcao('dashboard')}>
                  Gerar dashboard
                </Button>
              </Space>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
        <Card style={{ background: '#f3eaff', borderRadius: '0 0 12px 12px', boxShadow: '0 -2px 8px #e6e6e6', margin: 0, position: 'sticky', bottom: 0, zIndex: 2 }} bodyStyle={{ padding: 12 }}>
          <Input.Group compact>
            <Input
              style={{ width: '85%' }}
              placeholder="Digite um tema, empresa ou assunto..."
              value={input}
              onChange={e => setInput(e.target.value)}
              onPressEnter={() => handleSend()}
              disabled={loading}
            />
            <Button type="primary" icon={<SendOutlined />} onClick={() => handleSend()} disabled={loading} />
          </Input.Group>
        </Card>
      </div>
    </div>
  );
};

export default Chat;
